		private void DrawText(string text, ref Texture2D tex)
		{
			RenderTarget2D renderTarget2D = new RenderTarget2D(this.sc.GraphicsDevice, 900, 200, true, SurfaceFormat.Color, DepthFormat.None);
			this.sc.GraphicsDevice.SetRenderTarget(renderTarget2D);
			this.sc.GraphicsDevice.Clear(Color.Transparent);
			this.spriteBatch.Begin(SpriteSortMode.Deferred, BlendState.AlphaBlend);
