				{
					Vector3 vector = Vector3.Transform(Vector3.Zero, this.wallguns[i] * Matrix.CreateTranslation(3000f, 0f, 3000f));
					float num2 = Vector3.DistanceSquared(this.myPlayer.displayState.npcPosition, vector);
